 urlPath.contains(".png", ignoreCase = true) -> "png"
 urlPath.contains(".webp", ignoreCase = true) -> "webp"
 else -> "jpg" // デフォルトはjpg
}
val fileName = String.format("%03d.%s", index + 1, extension)
```

The problem is that for URLs like `https://picsum.photos/200/200?random=1`, the `url.path` returns `/200/200` and doesn't contain any file extension. But worse, it looks like somewhere in the code it's still using the full URL as part of the filename, creating invalid paths like `001.photos/200/200?random=1`.

