+ // サーバーから画像をダウンロードする関数
+ fun downloadImagesFromServer(imageUrls: List<String>) {
+ CoroutineScope(Dispatchers.IO).launch {
+ try {
+ val baseDir = getExternalFilesDir(null)
+ if (baseDir != null) {
+ val widgetImagesDir = File(baseDir, "WidgetImages")
+
+ if (!widgetImagesDir.exists()) {
+ widgetImagesDir.mkdirs()
+ }
+
+ imageUrls.forEachIndexed { index, imageUrl ->
+ try {
+ android.util.Log.d(
+ "MainActivity",
+ "Downloading image $index from: $imageUrl"
+ )
+
+ val url = URL(imageUrl)
+ val connection = url.openConnection()
+ val inputStream = connection.getInputStream()
+
+ // ファイル名を決定（拡張子をURLから取得）
+ val extension = imageUrl.substringAfterLast('.', "jpg")
+ val fileName = String.format("%03d.%s", index + 1, extension)
+ val outputFile = File(widgetImagesDir, fileName)
+
+ // ファイルにダウンロード
+ FileOutputStream(outputFile).use { outputStream ->
+ inputStream.copyTo(outputStream)
+ }
+
+ withContext(Dispatchers.Main) {
+ android.util.Log.d(
+ "MainActivity",
+ "Downloaded: ${outputFile.absolutePath}"
+ )
+ }
+
+ } catch (e: Exception) {
+ withContext(Dispatchers.Main) {
+ android.util.Log.e(
+ "MainActivity",
+ "Failed to download image $index: $imageUrl",
+ e
+ )
+ }
+ }
+ }
+
+ withContext(Dispatchers.Main) {
+ android.util.Log.d("MainActivity", "Image download completed")
+ // ダウンロード完了後にウィジェットを更新
+ notifyWidgetUpdate()
+ }
+ }
+ } catch (e: Exception) {
+ withContext(Dispatchers.Main) {
+ android.util.Log.e("MainActivity", "Error in download process", e)
+ }
+ }
+ }
+ }
+
+ private fun notifyWidgetUpdate() {
+ try {
+ val intent = android.content.Intent().apply {
+ component = android.content.ComponentName(
+ "com.seo4d696b75.android.glance_widget_demo",
+ "com.seo4d696b75.android.glance_widget_demo.widget.CounterWidgetProvider"
+ )
+ action = android.appwidget.AppWidgetManager.ACTION_APPWIDGET_UPDATE
+ }
+ sendBroadcast(intent)
+ android.util.Log.d("MainActivity", "Widget update notification sent")
+ } catch (e: Exception) {
+ android.util.Log.e("MainActivity", "Error notifying widget update", e)
+ }
+ }
