```
@@ -261,15 +261,7 @@
 */
 private fun setFallbackImage(views: RemoteViews, frameIndex: Int) {
- // drawableリソースの代わりに、フォールバック用の単一画像を使用
- // または、キャッシュされていない場合のプレースホルダー画像
- val fallbackDrawables = arrayOf(
- R.drawable.testanims_001, R.drawable.testanims_002, R.drawable.testanims_003,
- R.drawable.testanims_004, R.drawable.testanims_005, R.drawable.testanims_006,
- R.drawable.testanims_007, R.drawable.testanims_008, R.drawable.testanims_009,
- R.drawable.testanims_010
- )
-
- val drawableIndex = frameIndex.coerceIn(0, fallbackDrawables.size - 1)
- views.setImageViewResource(R.id.background_image, fallbackDrawables[drawableIndex])
+ // drawableリソースを使用しない - 透明背景のみ使用
+ views.setImageViewResource(R.id.background_image, android.R.color.transparent)
+ Log.w(TAG, "Using transparent fallback for frame $frameIndex - no drawable resources")
 }

