 putExtra(AppWidgetManager.EXTRA_APPWIDGET_IDS, appWidgetIds)
 }
 context.sendBroadcast(intent)
 }
 } catch (e: Exception) {
 // エラーログ
 android.util.Log.e("SettingScreen", "Failed to notify widget update", e)
